<?php $editing=isset($item['id']);$base=$type==='page'?'pages':'posts'; ?>
<?php if(!empty($error)):?><div class="flash error"><?= e($error) ?></div><?php endif;?>
<form method="post" action="<?= $editing?'/admin/'.e($base).'/'.(int)$item['id']:'/admin/'.e($base) ?>" data-content-form><?= csrf_field() ?><div class="editor-grid"><div class="editor-main"><section class="panel editor-card"><input class="title-input" name="title" value="<?= e($item['title']??'') ?>" placeholder="Add title" required data-title-input><div class="permalink"><span>Permalink</span><span class="url-prefix">/<?= $type==='post'?'blog/':'' ?></span><input name="slug" value="<?= e($item['slug']??'') ?>" placeholder="generated-from-title" data-slug-input></div><div class="field"><label>Excerpt</label><textarea name="excerpt" class="excerpt" placeholder="A short summary used by themes and search results."><?= e($item['excerpt']??'') ?></textarea></div><div class="field"><label>Content</label><div class="editor-toolbar" data-editor-toolbar><button type="button" data-tag="strong"><b>B</b></button><button type="button" data-tag="em"><i>I</i></button><button type="button" data-wrap="h2">H2</button><button type="button" data-wrap="blockquote">❝</button><button type="button" data-link>Link</button></div><textarea name="body" class="code-editor" data-editor-body placeholder="Write your content… HTML is allowed for trusted editors."><?= e($item['body']??'') ?></textarea></div></section>
<section class="panel"><div class="panel-head"><div><h2>Search appearance</h2><p>Optional metadata. Blank fields fall back to title and excerpt.</p></div></div><div class="field"><label>SEO title <span class="counter" data-count-for="seo_title">0/60</span></label><input name="seo_title" value="<?= e($item['seo_title']??'') ?>" maxlength="255" data-count-target="seo_title"></div><div class="field"><label>Meta description <span class="counter" data-count-for="seo_description">0/160</span></label><textarea name="seo_description" class="short" maxlength="320" data-count-target="seo_description"><?= e($item['seo_description']??'') ?></textarea></div><div class="field"><label>Canonical URL</label><input name="canonical_url" type="url" value="<?= e($item['canonical_url']??'') ?>" placeholder="https://example.com/preferred-url"></div></section>
<?php if($editing && $revisions):?><section class="panel"><div class="panel-head"><div><h2>Recent revisions</h2><p>AfiuCMS stores a snapshot before every update.</p></div></div><div class="revision-list"><?php foreach($revisions as $rev):?><div><strong><?= e($rev['created_at']) ?></strong><span><?= e($rev['user_name']) ?></span></div><?php endforeach;?></div></section><?php endif;?></div>
<aside class="editor-side"><section class="panel sticky-panel"><div class="field"><label>Status</label><select name="status"><option value="draft"<?= selected($item['status']??'draft','draft') ?>>Draft</option><option value="published"<?= selected($item['status']??'draft','published') ?>>Published</option></select></div><div class="field"><label>Featured image</label><select name="featured_media_id"><option value="0">None</option><?php foreach($media as $m):?><option value="<?= (int)$m['id'] ?>"<?= selected((string)($item['featured_media_id']??''),(string)$m['id']) ?>><?= e($m['original_name']) ?></option><?php endforeach;?></select></div><div class="publish-actions"><button class="btn primary wide" type="submit"><?= $editing?'Save changes':'Create '.e($type) ?></button><a class="btn ghost wide" href="/admin/<?= e($base) ?>">Cancel</a></div></section>
<?php if($type==='post'):?><section class="panel"><h3>Categories</h3><div class="check-list"><?php foreach($categories as $cat):?><label><input type="checkbox" name="categories[]" value="<?= (int)$cat['id'] ?>"<?= checked(in_array((int)$cat['id'],$selected,true)) ?>> <span><?= e($cat['name']) ?></span></label><?php endforeach;?><?php if(!$categories):?><p class="muted">Create categories from Content → Categories.</p><?php endif;?></div><div class="field"><label>Tags</label><input name="tags" value="<?= e($tags) ?>" placeholder="design, news, launch"><small>Separate tags with commas.</small></div></section><?php endif;?></aside></div></form>